<template><div v-loading="loading"><p class="hint">平台退款先保存再转业务退款；转单失败仍会阻断新增履约。退款单不新增销售订单。</p><el-table :data="rows" empty-text="当前订单暂无平台退款记录"><el-table-column prop="refund_id" label="平台退款单号" min-width="220" /><el-table-column prop="platform_oid" label="平台子单号" min-width="220" /><el-table-column prop="refund_fee" label="金额" width="110" /><el-table-column label="平台 / 转单" min-width="220"><template slot-scope="s">{{ s.row.platform_status==='SUCCESS' ? '平台退款成功' : label(s.row.platform_status) }}<div class="hint">{{ s.row.conversion_state==='SUCCESS' ? '已转业务退款单' : label(s.row.conversion_state) }}</div><div v-if="s.row.business">{{ label(s.row.business.purpose) }} · {{ label(s.row.business.goods_state) }}</div><div class="warning">{{ s.row.source_error || s.row.conversion_error }}</div></template></el-table-column><el-table-column label="操作" width="200"><template slot-scope="s"><el-button type="text" @click="$refs.platform.open(s.row.id)">平台退款</el-button><el-button v-if="s.row.business_refund_id" type="text" @click="$refs.business.open(s.row.business_refund_id)">业务退款</el-button></template></el-table-column></el-table><refund-detail ref="platform" @changed="load" /><refund-detail ref="business" business @changed="load" /></div></template>
<script>
import { orderRefunds } from '@/api/order/refund'
import { label } from './refundLabels'
import RefundDetail from './RefundDetail'
export default { name: 'OrderRefundRecords', components: { RefundDetail }, props: { orderId: { type: Number, required: true } }, data: () => ({ loading: false, rows: [] }), watch: { orderId: { immediate: true, handler() { this.load() } } }, methods: { label, async load() { this.loading = true; try { const r = (await orderRefunds(this.orderId)).data; this.rows = r.platform.map(p => ({ ...p, business: r.business.find(b => Number(b.id) === Number(p.business_refund_id)) })) } finally { this.loading = false } } } }
</script>
<style scoped>.hint{font-size:12px;color:#8290a4;line-height:1.8}.warning{color:#b77515}</style>
